STYLE REFERENCE: Photoreal, vibrant open-world action-game aesthetic — naturalistic sun-drenched color grading, dynamic third-person gameplay camera, cinematic framing typical of open-world exploration moments DURATION: 10 seconds, single continuous take, no cuts ASPECT: 9:16 vertical SETTING: A sunny tropical beach at midday — turquoise water, white sand, scattered palm trees, gentle rolling waves, bright natural sunlight with soft lens flare off the water CHARACTERS: - MAIN CHARACTER:
@image1
— use this reference image as the exact locked visual identity, maintaining the same face, hair, body proportions, and outfit precisely as shown, from every angle, with no design deviation - WOMAN: a beautiful woman standing near the shoreline in casual beachwear, smiling warmly — generic, non-specific appearance CAMERA: Third-person perspective, open-world-game-style follow-cam. Behind-the-shoulder tracking during the walk and run, then a dynamic arcing camera move that swings around the character during the single backflip to capture it cinematically, settling low near the water surface for the dive and splash. HUD OVERLAY: A small minimap in the bottom-left corner of the screen (radar-style circle showing the character's position), unobtrusive — no other UI elements. BEAT-BY-BEAT: 0:00–0:02 — Protagonist walks onto the beach, camera trailing behind the shoulder; they spot the woman standing near the waterline 0:02–0:03 — Protagonist raises a hand and waves, calling out "Hello!" with a warm grin; the woman smiles and waves back 0:03–0:06 — Protagonist turns and breaks into a run down the beach toward the water, sand kicking up behind them, camera dynamically following at running speed 0:06–0:08 — Reaching the shoreline, the protagonist leaps upward and performs exactly one single backflip — one complete 360° rotation, performed only once — as the camera arcs fluidly around the rotation to capture it from a dramatic angle, sunlight flaring across the frame mid-rotation 0:08–0:10 — Protagonist completes the single rotation and plunges into the water with a splash; camera settles low at the water's surface, capturing the splash and rippling water sparkling in the sunlight CHARACTER DIALOGUE: "Hello!" (warm, friendly, called out while waving) — no on-screen subtitles beyond the minimap HUD AUDIO: Gentle ocean waves, seagulls calling, a light breeze, bare feet on sand, the friendly greeting line, a satisfying splash as the character hits the water, an upbeat breezy ambient undertone NEGATIVE PROMPT: no on-screen text or subtitles, no logos or brand names, no extra HUD elements beyond the minimap, no watermark, no extra unintended cuts, no extra limbs, no design drift on the protagonist from the reference image, no first-person view, no sexualized content, no real identifiable person depicted as the woman, no multiple flips or repeated rotations — only one single backflip performed once

{
  "archetype": "Competitive cooking show finale",
  "duration": "30s",
  "prompt": {
    "concept": {
      "title": "The Judge Who Never Speaks",
      "description": "A legendary, feared food critic known for never speaking during judging takes one bite of a nervous contestant's dish. His face goes through a slow, dramatic silent transformation while the entire kitchen holds its breath.",
      "rhythm_structure": {
        "0-8s": "Tense kitchen setup, contestant plating nervously",
        "8-13s": "Dish is presented, judge picks up fork in total silence",
        "13-15s": "The bite — extreme close-up, no reaction yet",
        "15-25s": "Slow silent facial transformation, crew and contestant frozen watching",
        "25-30s": "Single word verdict, contestant collapses in relief/joy"
      }
    },
    "character_identity_lock": {
      "maintain_same_character": true,
      "identity": {
        "age_gender": "stern man in his 60s",
        "hair": "silver, perfectly groomed",
        "face": "deep set eyes, unreadable resting expression, weathered but composed",
        "clothing": "immaculate black suit, no tie, single cufflink glint",
        "accessories": "antique pocket watch he never uses, always in pocket"
      },
      "strict_consistency": ["Same stern face throughout", "Never speaks until the final word", "Same suit and posture"],
      "color_rule": "Cool steel-blue kitchen lighting throughout; warm golden light isolates his face during the reaction",
      "core_concept": "Maximum tension built entirely through silence and micro-expression, not dialogue",
      "physics_rules": "Fully realistic, no exaggeration — the drama is in restraint, not spectacle"
    },
    "camera_direction": {
      "shot_type": "Slow deliberate cinematography, extreme close-ups, minimal cuts",
      "forbidden": ["No fast cuts during the reaction", "No dialogue until the final word", "No exaggerated cartoonish faces"],
      "camera_journey": "Wide steady shot of tense kitchen, slow push into contestant's shaking hands plating, extreme close-up on the fork lifting, held close-up on judge's face for the full reaction, cut wide for the final word and contestant's collapse."
    },
    "visual_style": {
      "overall": "High-end prestige cooking show cinematography, moody and cinematic rather than bright reality TV",
      "inspired_by": ["The Bear tension", "MasterChef finale drama", "Ratatouille's critic scene gravity"],
      "color_palette": ["Cool steel blue kitchen", "Warm isolated golden spotlight on judge", "Deep black suit contrast"],
      "materials_and_texture": "Realistic steam, plate ceramics, fabric sheen, sweat on contestant's brow"
    },
    "motion_language": {
      "follows_music": true,
      "tension_strings": "Single sustained note building through the silent reaction",
      "silence_beat": "Near-total ambient silence for 8+ seconds during the face transformation",
      "release_hit": "Single soft piano note on the verdict word"
    },
    "storyboard": {
      "total_beats": 6,
      "beats": [
        {"id": "01", "time": "0-8s", "description": "Wide shot of a tense professional kitchen. Contestant's hands shake slightly while plating a delicate dish. Crew watches silently."},
        {"id": "02", "time": "8-13s", "description": "Judge sits at the tasting table, expressionless. Dish is placed before him. He picks up the fork with slow deliberate precision."},
        {"id": "03", "time": "13-15s",
"description": "Extreme close-up as he takes the bite. Chews once, twice. Absolutely no readable expression yet."},
        {"id": "04", "time": "15-25s", "description": "Held close-up on his face as it slowly shifts — eyebrow twitch, eyes widen slightly, jaw tightens, then a barely perceptible softening. Contestant and crew frozen, not breathing."},
        {"id": "05", "time": "25-28s", "description": "He sets down the fork, looks up, pauses, then says one single quiet word: 'Exceptional.'"},
        {"id": "06", "time": "28-30s", "description": "Contestant's knees buckle in relief, crew erupts silently into hugs. Freeze on the judge allowing the faintest smile."}
      ]
    }
  }
}
